const helpers = this.helpers;
const baseUrl = 'https://suporte.araraquara.sp.gov.br/api.php/v1';
const appToken = $('Carregar Tokens').first().json.app_token;
const userToken = $('Carregar Tokens').first().json.user_token;

const I_FORM = 'Glpi%5CForm%5CForm';
const I_SEC = 'Glpi%5CForm%5CSection';
const I_Q = 'Glpi%5CForm%5CQuestion';
const I_D = 'Glpi%5CForm%5CDestination%5CFormDestination';

function mapType(t) {
  const m = {
    text:     'Glpi\\Form\\QuestionType\\QuestionTypeShortText',
    textarea: 'Glpi\\Form\\QuestionType\\QuestionTypeLongText',
    email:    'Glpi\\Form\\QuestionType\\QuestionTypeEmail',
    date:     'Glpi\\Form\\QuestionType\\QuestionTypeShortText',
    number:   'Glpi\\Form\\QuestionType\\QuestionTypeNumber',
    select:   'Glpi\\Form\\QuestionType\\QuestionTypeDropdown',
    radios:   'Glpi\\Form\\QuestionType\\QuestionTypeRadio',
    regex:    'Glpi\\Form\\QuestionType\\QuestionTypeShortText',
    location: 'Glpi\\Form\\QuestionType\\QuestionTypeItemDropdown',
    user:     'Glpi\\Form\\QuestionType\\QuestionTypeItemDropdown'
  };
  return m[t] || 'Glpi\\Form\\QuestionType\\QuestionTypeShortText';
}

function extraDataPorTipo(q) {
  if (q.type === 'location') {
    return JSON.stringify({
      itemtype: 'Location', categories_filter: [],
      root_items_id: 0, subtree_depth: 0, selectable_tree_root: false
    });
  }
  if (q.type === 'user') {
    return JSON.stringify({ itemtype: 'User' });
  }
  if (q.values && (q.type === 'select' || q.type === 'radios')) {
    return JSON.stringify({ options: q.values });
  }
  return null;
}

function gerarConfigTicket(def) {
  return {
    'glpi-form-destination-commonitilfield-titlefield': { value: `Solicitacao - ${def.nome}` },
    'glpi-form-destination-commonitilfield-contentfield_auto': true,
    'glpi-form-destination-commonitilfield-observerfield': { strategies: ['last_valid_answer'], specific_question_ids: [], specific_itilactors_ids: [] },
    'glpi-form-destination-commonitilfield-requesttypefield': { strategy: 'specific_value', specific_question_id: null, specific_request_type: 1 },
    'glpi-form-destination-commonitilfield-linkeditilobjectsfield': { strategy_configs: [{ linktype: '', strategy: null, specific_itilobject: [], specific_question_ids: [], specific_destination_ids: [] }] }
  };
}

async function callRaw(method, url, headers, body) {
  const opts = { method, url, headers, json: false, returnFullResponse: true, ignoreHttpStatusErrors: true };
  if (body !== undefined) opts.body = typeof body === 'string' ? body : JSON.stringify(body);
  const resp = await helpers.httpRequest(opts);
  let parsed = resp.body;
  if (typeof parsed === 'string') { try { parsed = JSON.parse(parsed); } catch(_) {} }
  return { status: resp.statusCode || resp.status, body: parsed, bodyRaw: typeof resp.body === 'string' ? resp.body.substring(0,400) : '' };
}

const def = $input.first().json;
const result = { menu: def.menu, nome: def.nome, categoria_glpi: def.ticket.categoria_glpi };

const initRes = await callRaw('GET', `${baseUrl}/initSession`, {
  'App-Token': appToken,
  'Authorization': `user_token ${userToken}`
});
if (initRes.status !== 200 || !initRes.body || !initRes.body.session_token) {
  return [{ json: { ...result, status: 'erro_auth' }}];
}
const sessionToken = initRes.body.session_token;
const H = { 'App-Token': appToken, 'Session-Token': sessionToken, 'Content-Type': 'application/json' };

async function callApi(method, path, body) {
  const r = await callRaw(method, `${baseUrl}${path}`, H, body);
  if (r.status >= 400) {
    throw new Error(JSON.stringify({ method, path, status: r.status, payload: body, resposta: r.body || r.bodyRaw }));
  }
  return r.body;
}

try {
  // Idempotencia
  const buscaUrl = `/${I_FORM}?searchText[name]=${encodeURIComponent(def.nome)}&is_deleted=0&range=0-10`;
  const busca = await callApi('GET', buscaUrl);
  const arr = Array.isArray(busca) ? busca : (busca && busca.data ? busca.data : []);
  const existe = arr.find(f => f && f.name === def.nome);
  if (existe) {
    result.status = 'ja_existe';
    result.form_id = existe.id;
    result.url = `https://suporte.araraquara.sp.gov.br/Form/Render/${existe.id}`;
    try { await callRaw('GET', `${baseUrl}/killSession`, H); } catch(_) {}
    return [{ json: result }];
  }

  const formRes = await callApi('POST', `/${I_FORM}`, {
    input: {
      name: def.nome, description: def.descricao, illustration: 'report-issue',
      is_active: 1, is_recursive: 1, is_deleted: 0, is_draft: 0, is_pinned: 0,
      entities_id: 0, forms_categories_id: 0
    }
  });
  const formId = formRes.id;

  const secList = await callApi('GET', `/${I_SEC}?range=0-100`);
  const secsArr = Array.isArray(secList) ? secList : (secList.data || []);
  const minhasSec = secsArr.filter(s => s && s.forms_forms_id === formId);
  if (minhasSec.length === 0) throw new Error('Section default ausente');

  const minhasSecoes = [];
  const sec0 = def.secoes[0];
  await callApi('PUT', `/${I_SEC}/${minhasSec[0].id}`, { input: { id: minhasSec[0].id, name: sec0.nome, rank: 0 }});
  minhasSecoes.push({ id: minhasSec[0].id, def: sec0 });

  let rank = 1;
  for (let i = 1; i < def.secoes.length; i++) {
    const sec = def.secoes[i];
    const secRes = await callApi('POST', `/${I_SEC}`, { input: { forms_forms_id: formId, name: sec.nome, description: '', rank: rank++ }});
    minhasSecoes.push({ id: secRes.id, def: sec });
  }

  for (const { id: secId, def: sec } of minhasSecoes) {
    let qRank = 0;
    for (const q of sec.perguntas) {
      const body = { input: {
        forms_sections_id: secId, name: q.label, description: '',
        type: mapType(q.type), is_mandatory: q.required ? 1 : 0,
        vertical_rank: qRank++, horizontal_rank: null,
        default_value: null, extra_data: null,
        visibility_strategy: '', conditions: '[]',
        validation_strategy: '', validation_conditions: '[]'
      }};
      const xd = extraDataPorTipo(q);
      if (xd) body.input.extra_data = xd;
      await callApi('POST', `/${I_Q}`, body);
    }
  }

  const destList = await callApi('GET', `/${I_D}?range=0-100`);
  const destArr = Array.isArray(destList) ? destList : (destList.data || []);
  const minhasDest = destArr.filter(d => d && d.forms_forms_id === formId);
  if (minhasDest.length === 0) throw new Error('Destination default ausente');

  await callApi('PUT', `/${I_D}/${minhasDest[0].id}`, {
    input: { id: minhasDest[0].id, name: `Chamado - ${def.nome}`, config: JSON.stringify(gerarConfigTicket(def)) }
  });

  result.status = 'criado';
  result.form_id = formId;
  result.destination_id = minhasDest[0].id;
  result.url = `https://suporte.araraquara.sp.gov.br/Form/Render/${formId}`;
} catch(e) {
  result.status = 'erro';
  result.erro = e.message;
}

try { await callRaw('GET', `${baseUrl}/killSession`, H); } catch(_) {}
return [{ json: result }];

const items = $input.all().map(i => i.json);
const stats = {
  total: items.length,
  criados: items.filter(r => r.status === 'criado').length,
  ja_existiam: items.filter(r => r.status === 'ja_existe').length,
  erros: items.filter(r => r.status === 'erro' || (r.status && r.status.startsWith('erro'))).length
};
return [{ json: {
  sucesso: stats.erros === 0,
  stats,
  resultados: items,
  erros_detalhe: items.filter(r => r.status === 'erro' || (r.status && r.status.startsWith('erro')))
}}];

